from pathlib import Path
import json
import re
from datetime import datetime
import pandas as pd

REPORT_START = pd.Timestamp('2024-03-15 00:00:00', tz='UTC')
REPORT_END = pd.Timestamp('2024-03-16 00:00:00', tz='UTC')
MONTHS = {m: i for i, m in enumerate(['January','February','March','April','May','June','July','August','September','October','November','December'], start=1)}

farms = pd.read_csv('/app/dataset/farms.csv')
farms['farm_name_norm'] = farms['farm_name'].str.strip().str.lower()
registry = pd.read_csv('/app/dataset/farm_registry.csv')
registry['farm_name_norm'] = registry['farm_name'].str.strip().str.lower()
meta = registry.merge(farms[['farm_name_norm','timezone','installed_capacity_kw']], on='farm_name_norm', how='left')
meta = meta.set_index('farm_id')
with open('/app/dataset/sensors_calibration.json') as f:
    cal = json.load(f)['enterprise_platform']['deployment_environments']['system_config']['farms']
notes = Path('/app/dataset/maintenance_notes.txt').read_text()

name_to_id = {row.farm_name_norm: idx for idx, row in meta.iterrows()}
name_display = {idx: row.farm_name_norm for idx, row in meta.iterrows()}

# parse maintenance
completed = {fid: [] for fid in meta.index}
for line in notes.splitlines():
    if 'status: completed' not in line.lower():
        continue
    line_l = line.lower()
    farm_id = None
    for fid, row in meta.iterrows():
        if row.farm_name_norm in line_l:
            farm_id = fid
            break
    if not farm_id:
        continue
    m = re.search(r'on the (\d+)(?:st|nd|rd|th)? of ([A-Za-z]+) from (\d{2}:\d{2}) to (\d{2}:\d{2}) local time', line, re.I)
    if not m:
        m = re.search(r'on ([A-Za-z]+) (\d+)(?:st|nd|rd|th)?(?:,)?(?: from|, starting at) (\d{2}:\d{2})(?: to| and finishing at) (\d{2}:\d{2}) local time', line, re.I)
        if m:
            month, day, start_s, end_s = m.groups()
        else:
            raise SystemExit(f'could not parse maintenance line: {line}')
    else:
        day, month, start_s, end_s = m.groups()
    month_num = MONTHS[month.capitalize()]
    day = int(day)
    start_local = pd.Timestamp(f'2024-{month_num:02d}-{day:02d} {start_s}').tz_localize(meta.loc[farm_id, 'timezone'])
    end_local = pd.Timestamp(f'2024-{month_num:02d}-{day:02d} {end_s}').tz_localize(meta.loc[farm_id, 'timezone'])
    completed[farm_id].append((start_local, end_local))
print('maintenance', {k:[(s.isoformat(),e.isoformat()) for s,e in v] for k,v in completed.items() if v})


def read_df(path):
    raw = path.read_bytes()
    enc = 'utf-16' if raw.startswith((b'\xff\xfe', b'\xfe\xff')) else 'utf-8-sig'
    text = path.read_text(encoding=enc)
    delim = ';' if text.splitlines()[3].count(';') > text.splitlines()[3].count(',') else ','
    df = pd.read_csv(path, encoding=enc, sep=delim, skiprows=3, dtype=str).drop_duplicates()
    return df

def clean_num(series):
    s = series.astype(str).str.strip().str.replace(r'(?<=\d)\.(?=\d{3}(?:\D|$))', '', regex=True).str.replace(',', '.', regex=False)
    return pd.to_numeric(s, errors='coerce')

def parse_ts(series):
    s = series.astype(str).str.strip()
    return pd.to_datetime(s, format='%Y-%m-%d %H:%M:%S', errors='coerce').fillna(pd.to_datetime(s, format='%d.%m.%Y %H:%M:%S', errors='coerce'))

def factor(unit):
    return {'kwh':1.0,'mwh':1000.0,'wh':0.001,'btu':0.00029307107,'kw':1.0}[unit.strip().lower()]

variants = {}
for local_ts in [True]:
    for cap_filter in [False, True]:
        for power_mode in ['nominal', 'actual_to_next']:
            key = (local_ts, cap_filter, power_mode)
            out = {}
            for fid in meta.index:
                df = read_df(Path(f'/app/dataset/production_{fid}.csv'))
                cols = list(df.columns)
                ts_col = next(c for c in cols if c.strip() == 'timestamp')
                temp_col = next(c for c in cols if c.strip() == 'inverter_temperature_C')
                val_name = cal[fid]['calibration_data']['value_column_name']
                val_col = val_name if val_name in cols else [c for c in cols if c.strip()==val_name.strip()][0]
                ts_local_naive = parse_ts(df[ts_col])
                ts_local = ts_local_naive.dt.tz_localize(meta.loc[fid,'timezone'], ambiguous='NaT', nonexistent='NaT')
                ts_utc = ts_local.dt.tz_convert('UTC') if ts_local.notna().any() else ts_local
                step_diffs = ts_local_naive.dropna().sort_values().drop_duplicates().diff().dropna()
                step = step_diffs.value_counts().idxmax() if not step_diffs.empty else pd.Timedelta(0)
                vals = clean_num(df[val_col]) - float(cal[fid]['calibration_data']['calibration_offset'])
                temps = clean_num(df[temp_col])
                unit = cal[fid]['sensor_info']['unit']
                kind = cal[fid]['sensor_info']['reading_type']
                norm = vals * factor(unit)
                valid = ts_utc.notna() & norm.notna() & (vals >= 0)
                if cap_filter:
                    limit = meta.loc[fid,'installed_capacity_kw'] * 1.15
                    if kind == 'energy':
                        limit *= step / pd.Timedelta(hours=1)
                    valid &= norm <= limit
                # safety windows
                spikes = ts_local[temps > 85].dropna().tolist()
                if spikes:
                    bad = pd.Series(False, index=df.index)
                    for spike in spikes:
                        bad |= (ts_local > spike) & (ts_local <= spike + pd.Timedelta(minutes=45))
                    valid &= ~bad
                # maintenance
                for start, end in completed[fid]:
                    valid &= ~((ts_local >= start) & (ts_local < end))
                valid &= (ts_utc >= REPORT_START) & (ts_utc < REPORT_END)
                if kind == 'energy':
                    total = norm[valid].sum()
                else:
                    if power_mode == 'nominal':
                        total = norm[valid].sum() * (step / pd.Timedelta(hours=1))
                    else:
                        # use actual gap to next timestamp, capped at 2x nominal to avoid runaway missing gaps
                        t = ts_local[valid].sort_values()
                        # align norm to sorted valid timestamps
                        sub = pd.DataFrame({'ts': ts_local[valid], 'norm': norm[valid]}).sort_values('ts')
                        if step == pd.Timedelta(0):
                            total = 0
                        else:
                            next_ts = sub['ts'].shift(-1)
                            dur = (next_ts - sub['ts']).fillna(step)
                            dur = dur.clip(upper=step*2)
                            total = (sub['norm'] * (dur / pd.Timedelta(hours=1))).sum()
                out[fid] = int(round(float(total))) if pd.notna(total) else 0
            variants[key] = out

for key, out in variants.items():
    print('\nVARIANT', key)
    print(out)
