from __future__ import annotations

import json
import re
from pathlib import Path

import pandas as pd


DATASET_DIR = Path("/app/dataset")
REPORT_START_UTC = pd.Timestamp("2024-03-15 00:00:00", tz="UTC")
REPORT_END_UTC = pd.Timestamp("2024-03-16 00:00:00", tz="UTC")
BTU_TO_KWH = 0.00029307107
CAPACITY_MARGIN = 1.15
MONTHS = {
    "january": 1,
    "february": 2,
    "march": 3,
    "april": 4,
    "may": 5,
    "june": 6,
    "july": 7,
    "august": 8,
    "september": 9,
    "october": 10,
    "november": 11,
    "december": 12,
}


def _normalize_name(value: str) -> str:
    return value.strip().lower()


def _coerce_numeric(series: pd.Series) -> pd.Series:
    text = series.astype(str).str.strip()
    text = text.str.replace(r"(?<=\d)\.(?=\d{3}(?:\D|$))", "", regex=True)
    text = text.str.replace(",", ".", regex=False)
    return pd.to_numeric(text, errors="coerce")


def _parse_local_timestamps(series: pd.Series) -> pd.Series:
    text = series.astype(str).str.strip()
    iso = pd.to_datetime(text, format="%Y-%m-%d %H:%M:%S", errors="coerce")
    dot = pd.to_datetime(text, format="%d.%m.%Y %H:%M:%S", errors="coerce")
    return iso.fillna(dot)


def _unit_factor(unit: str) -> float:
    normalized = unit.strip().lower()
    if normalized == "kwh":
        return 1.0
    if normalized == "mwh":
        return 1000.0
    if normalized == "wh":
        return 0.001
    if normalized == "btu":
        return BTU_TO_KWH
    if normalized == "kw":
        return 1.0
    raise ValueError(f"Unsupported unit: {unit!r}")


def _read_farm_metadata() -> pd.DataFrame:
    farms = pd.read_csv(DATASET_DIR / "farms.csv")
    farms["farm_name_norm"] = farms["farm_name"].map(_normalize_name)

    registry = pd.read_csv(DATASET_DIR / "farm_registry.csv")
    registry["farm_name_norm"] = registry["farm_name"].map(_normalize_name)

    merged = registry.merge(
        farms[["farm_name_norm", "timezone", "installed_capacity_kw"]],
        on="farm_name_norm",
        how="left",
    )
    return merged.set_index("farm_id")


def _read_calibration() -> dict[str, dict]:
    with (DATASET_DIR / "sensors_calibration.json").open() as f:
        data = json.load(f)
    return data["enterprise_platform"]["deployment_environments"]["system_config"][
        "farms"
    ]


def _resolve_column(columns: list[str], target: str) -> str:
    if target in columns:
        return target

    matches = [column for column in columns if column.strip() == target.strip()]
    if matches:
        return matches[0]

    raise KeyError(f"Column {target!r} not found in {columns!r}")


def _read_production_csv(path: Path) -> pd.DataFrame:
    raw = path.read_bytes()
    encoding = "utf-16" if raw.startswith((b"\xff\xfe", b"\xfe\xff")) else "utf-8-sig"
    text = path.read_text(encoding=encoding)
    header_line = text.splitlines()[3]
    separator = ";" if header_line.count(";") > header_line.count(",") else ","
    return pd.read_csv(path, encoding=encoding, sep=separator, skiprows=3, dtype=str).drop_duplicates()


def _nominal_interval(local_timestamps: pd.Series) -> pd.Timedelta:
    sorted_unique = local_timestamps.dropna().sort_values().drop_duplicates()
    deltas = sorted_unique.diff().dropna()
    if deltas.empty:
        return pd.Timedelta(0)
    return deltas.value_counts().idxmax()


def _build_safety_mask(local_timestamps: pd.Series, temperatures_c: pd.Series) -> pd.Series:
    mask = pd.Series(False, index=local_timestamps.index)
    spike_times = local_timestamps[temperatures_c > 85.0].dropna()
    for spike_time in spike_times:
        mask |= (local_timestamps > spike_time) & (
            local_timestamps <= spike_time + pd.Timedelta(minutes=45)
        )
    return mask


def _read_completed_maintenance_windows(
    metadata: pd.DataFrame,
) -> dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]]:
    windows: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]] = {
        farm_id: [] for farm_id in metadata.index
    }
    notes = (DATASET_DIR / "maintenance_notes.txt").read_text()

    pattern_a = re.compile(
        r"on the (\d+)(?:st|nd|rd|th)? of ([A-Za-z]+) from (\d{2}:\d{2}) to (\d{2}:\d{2}) local time",
        re.IGNORECASE,
    )
    pattern_b = re.compile(
        r"on ([A-Za-z]+) (\d+)(?:st|nd|rd|th)?(?:,)?(?: from|, starting at) (\d{2}:\d{2})(?: to| and finishing at) (\d{2}:\d{2}) local time",
        re.IGNORECASE,
    )

    for line in notes.splitlines():
        if "status: completed" not in line.lower():
            continue

        line_lower = line.lower()
        farm_id = next(
            (
                candidate_id
                for candidate_id, row in metadata.iterrows()
                if row["farm_name_norm"] in line_lower
            ),
            None,
        )
        if farm_id is None:
            continue

        match = pattern_a.search(line)
        if match:
            day_text, month_text, start_text, end_text = match.groups()
        else:
            match = pattern_b.search(line)
            if not match:
                continue
            month_text, day_text, start_text, end_text = match.groups()

        month = MONTHS[month_text.strip().lower()]
        day = int(day_text)
        timezone = metadata.loc[farm_id, "timezone"]

        start = pd.Timestamp(f"2024-{month:02d}-{day:02d} {start_text}").tz_localize(
            timezone
        )
        end = pd.Timestamp(f"2024-{month:02d}-{day:02d} {end_text}").tz_localize(
            timezone
        )
        windows[farm_id].append((start, end))

    return windows


def _calculate_farm_total(
    farm_id: str,
    metadata: pd.DataFrame,
    calibration: dict[str, dict],
    maintenance_windows: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
) -> int:
    farm_meta = metadata.loc[farm_id]
    config = calibration[farm_id]
    df = _read_production_csv(DATASET_DIR / f"production_{farm_id}.csv")
    columns = list(df.columns)

    timestamp_column = _resolve_column(columns, "timestamp")
    temperature_column = _resolve_column(columns, "inverter_temperature_C")
    value_column = _resolve_column(
        columns, config["calibration_data"]["value_column_name"]
    )

    local_timestamps_naive = _parse_local_timestamps(df[timestamp_column])
    local_timestamps = local_timestamps_naive.dt.tz_localize(
        farm_meta["timezone"], ambiguous="NaT", nonexistent="NaT"
    )
    utc_timestamps = local_timestamps.dt.tz_convert("UTC")
    nominal_interval = _nominal_interval(local_timestamps_naive)
    interval_hours = nominal_interval / pd.Timedelta(hours=1) if nominal_interval else 0.0

    recorded_values = _coerce_numeric(df[value_column])
    true_values = recorded_values - float(config["calibration_data"]["calibration_offset"])
    temperatures_c = _coerce_numeric(df[temperature_column])

    reading_type = config["sensor_info"]["reading_type"]
    normalized_values = true_values * _unit_factor(config["sensor_info"]["unit"])

    valid = utc_timestamps.notna() & normalized_values.notna() & (true_values >= 0)

    if interval_hours > 0:
        physical_limit = float(farm_meta["installed_capacity_kw"]) * CAPACITY_MARGIN
        if reading_type == "energy":
            physical_limit *= interval_hours
        # The exports contain sentinel spikes that are far beyond the site capacity.
        valid &= normalized_values <= physical_limit

    valid &= ~_build_safety_mask(local_timestamps, temperatures_c)

    for start, end in maintenance_windows[farm_id]:
        valid &= ~((local_timestamps >= start) & (local_timestamps < end))

    valid &= (utc_timestamps >= REPORT_START_UTC) & (utc_timestamps < REPORT_END_UTC)

    if reading_type == "energy":
        total_kwh = float(normalized_values[valid].sum())
    else:
        if interval_hours <= 0:
            return 0
        total_kwh = float(normalized_values[valid].sum()) * interval_hours

    return int(round(total_kwh))


def answer() -> dict[str, int]:
    metadata = _read_farm_metadata()
    calibration = _read_calibration()
    maintenance_windows = _read_completed_maintenance_windows(metadata)

    return {
        farm_id: _calculate_farm_total(
            farm_id=farm_id,
            metadata=metadata,
            calibration=calibration,
            maintenance_windows=maintenance_windows,
        )
        for farm_id in metadata.index
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

